using System.Net;
public static class SmsPages
{
    static string E(string? x)=>WebUtility.HtmlEncode(x??"");
    public static string AddOptions(string html,bool active,string kind){if(!active)return html;var links=kind=="register"?"<a class='sms-option' href='/telefon-kayit'>Telefonla üye ol</a>":kind=="login"?"<a class='sms-option' href='/telefon-giris'>Telefonla giriş yap</a><a class='sms-option' href='/telefon-sifre'>SMS ile şifre yenile</a>":"<a class='sms-option' href='/telefon-sifre'>SMS ile şifre yenile</a>";var css="<style>.sms-options{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}.sms-option{display:flex;align-items:center;justify-content:center;min-height:44px;padding:10px 14px;border:1px solid #cbddec;border-radius:12px;background:#eff6ff;color:#1d5c99;font-weight:750;font-size:.86rem;text-decoration:none;flex:1;min-width:0;text-align:center}</style>";return html.Replace("</head>",css+"</head>",StringComparison.Ordinal).Replace("</form>","</form><div class='sms-options'>"+links+"</div>",StringComparison.Ordinal);}
    public static string Phone(string purpose,string error="",string id="",string notice=""){
        var register=purpose=="register";var title=register?"Telefonla üye olun":"Telefonla şifrenizi yenileyin";
        var body="<section class='member-card sms-auth'><p class='member-eyebrow'>İNOKSKAR HESAP MERKEZİ</p><h1>"+title+"</h1><p>"+(register?"Telefonunuzu doğrulayın, hesabınızı oluşturun.":"E-posta ile açılmış hesabınız için de kayıtlı telefonunuzu kullanabilirsiniz.")+"</p>"+(error.Length>0?"<p class='sms-error' role='alert'>"+E(error)+"</p>":"")+(notice.Length>0?"<p class='sms-notice' role='status'>"+E(notice)+"</p>":"");
        if(id.Length==0)body+="<form method='post' action='/telefon/kod'><input type='hidden' name='purpose' value='"+purpose+"'><label>Cep telefonu<input name='phone' type='tel' autocomplete='tel' maxlength='40' required placeholder='542 123 45 67'></label><button class='member-button'>Doğrulama kodu gönder</button></form>";
        else{body+="<form method='post' action='/telefon/onay'><input type='hidden' name='purpose' value='"+purpose+"'><input type='hidden' name='challenge' value='"+E(id)+"'><label>SMS doğrulama kodu<input name='code' inputmode='numeric' pattern='[0-9]{6}' maxlength='6' minlength='6' autocomplete='one-time-code' required></label>";if(register)body+="<label>Ad soyad<input name='name' autocomplete='name' minlength='2' maxlength='100' required></label><label>Firma (isteğe bağlı)<input name='businessName' maxlength='180' autocomplete='organization'></label>";body+="<label>"+(register?"Şifreniz":"Yeni şifreniz")+"<input name='password' type='password' autocomplete='new-password' minlength='8' maxlength='128' required></label><label>Şifre tekrar<input name='confirm' type='password' autocomplete='new-password' minlength='8' maxlength='128' required></label><button class='member-button'>"+(register?"Hesabımı oluştur":"Şifremi yenile")+"</button></form><p><a href='"+(register?"/telefon-kayit":"/telefon-sifre")+"'>Yeni kod iste</a></p>";}
        body+="<p><a href='/login'>Giriş sayfasına dön</a> · <a href='/kayit'>E-posta ile üye ol</a></p></section>";return Style(Membership.Shell(title,body));
    }
    public static string Login(string error="")=>Style(Membership.Shell("Telefonla giriş","<section class='member-card sms-auth'><p class='member-eyebrow'>İNOKSKAR HESAP MERKEZİ</p><h1>Telefonla giriş yapın</h1><p>Doğrulanmış telefonunuz ve şifrenizle devam edin.</p>"+(error.Length>0?"<p class='sms-error' role='alert'>"+E(error)+"</p>":"")+"<form method='post' action='/telefon-giris'><label>Cep telefonu<input name='phone' type='tel' autocomplete='tel' required maxlength='40'></label><label>Şifre<input name='password' type='password' required autocomplete='current-password' maxlength='128'></label><button class='member-button'>Giriş yap</button></form><p><a href='/telefon-sifre'>SMS ile şifre yenile</a> · <a href='/login'>E-posta ile giriş</a></p></section>"));
    static string Style(string html)=>html.Replace("</head>","<link rel='stylesheet' href='/sms-ui.css?v=sms-1'></head>",StringComparison.Ordinal);
    public static string Settings()=>Style(Membership.Shell("Sağlayıcı ayarları","<section class='member-card'><p class='member-eyebrow'>İLETİŞİM ALTYAPISI</p><h1>SMS sağlayıcısı</h1><p>Sağlayıcıyı seçin. Hazır bağlantı bilgilerini düzenleyebilir, Diğer seçeneğiyle yeni firma ekleyebilirsiniz.</p><form id='sms-settings'><div class='sms-grid'><label>Sağlayıcı<select id='sms-provider' name='id' required><option value=''>Yükleniyor…</option></select></label><label class='sms-check'><input name='enabled' type='checkbox'> Sistemi aktif et</label></div><div id='sms-fields' hidden><div class='sms-grid'><label>Firma adı<input name='name' maxlength='100' required></label><label>API adresi<input name='endpoint' type='text' maxlength='500' required></label><label>Gönderici başlığı / numarası<input name='sender' maxlength='50'></label><label>Kimlik doğrulama<select name='auth'><option value=''>Seçin</option><option value='basic'>Basic</option><option value='body'>İstek gövdesinde</option><option value='bearer'>Bearer</option><option value='header'>Özel API başlığı</option></select></label><label><span id='sms-user-label'>Kullanıcı adı / API anahtarı</span><input name='username' maxlength='320' autocomplete='off'></label><label><span id='sms-secret-label'>Şifre / anahtar</span><input name='secret' type='password' maxlength='1024' autocomplete='new-password'><small id='sms-secret-state'></small></label></div><div id='sms-custom' hidden><div class='sms-grid'><label>API başlık adı<input name='headerName' maxlength='80'></label><label>Başarı yanıtı alanı<input name='successPath' maxlength='200'></label><label>Başarı değeri<input name='successValue' maxlength='200'></label></div><label>JSON istek şablonu<textarea name='template' rows='6' maxlength='10000'></textarea><small>{phone}, {message}, {sender}, {username}, {secret} değişkenlerini kullanabilirsiniz. Alanlar JSON biçiminde hazırlanmalıdır.</small></label></div><div class='member-actions'><button class='member-button'>Kaydet ve uygula</button><button type='button' class='member-secondary' id='sms-disable'>Sistemi pasif yap</button></div></div></form><p id='sms-result' role='status' aria-live='polite'></p><div class='member-actions'><a class='member-secondary' href='/admin/mail'>Sağlayıcılara dön</a><a id='sms-messages-link' hidden class='member-secondary' href='/admin/sms/messages'>Mesaj yönetimi</a></div></section><script defer src='/sms-settings.js?v=sms-1'></script>",false,true));
    public static string Messages()=>Style(Membership.Shell("Mesaj yönetimi","<section class='member-card'><p class='member-eyebrow'>MÜŞTERİ İLETİŞİMİ</p><h1>SMS mesaj yönetimi</h1><form id='sms-message'><label>Alıcı<select name='customerId' id='sms-customer' required></select></label><label>Mesaj<textarea name='message' required maxlength='1000' rows='4'></textarea></label><button class='member-button'>Gönderim kuyruğuna al</button></form><p id='sms-result' role='status' aria-live='polite'></p></section><section class='member-card'><h2>Şifre yenileme talepleri</h2><div id='sms-requests'></div></section><section class='member-card'><h2>Gönderimler</h2><div id='sms-jobs'></div></section><script defer src='/sms-messages.js?v=sms-1'></script>",false,true));
}
